import type { KRailsTranslations } from "@/ui/krails/views/KRailsView/KRailsView";

export default function KRailsBuiltWith({
  translations,
  skipAnimation = false,
}: {
  translations: KRailsTranslations;
  skipAnimation?: boolean;
}) {
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-100px" });
  const effectiveInView = skipAnimation || isInView;

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.2,
        delayChildren: 0.1,
      },
    },
  };

  const itemVariants = {
    hidden: {
      opacity: 0,
      filter: "blur(10px)",
      y: 20,
    },
    visible: {
      opacity: 1,
      filter: "blur(0px)",
      y: 0,
      transition: {
        duration: 0.6,
        ease: [0.22, 1, 0.36, 1],
      },
    },
  };

  return (
    <section className={styles.section} ref={ref}>
      <div className={styles.container}>
        <motion.div
          className={styles.content}
          variants={containerVariants}
          initial={skipAnimation ? "visible" : "hidden"}
          animate={effectiveInView ? "visible" : "hidden"}
        >
          <motion.div
            className={styles.headingContainer}
            variants={{
              hidden: {
                opacity: 0,
                filter: "blur(10px)",
                y: 20,
              },
              visible: {
                opacity: 1,
                filter: "blur(0px)",
                y: 0,
                transition: {
                  duration: 0.6,
                  ease: [0.22, 1, 0.36, 1],
                },
              },
            }}
          >
            <h2 className={styles.heading}>{translations.builtWithHeading}</h2>
          </motion.div>

          <motion.div
            className={styles.logosContainer}
            variants={{
              hidden: {
                opacity: 0,
                filter: "blur(10px)",
                y: 20,
              },
              visible: {
                opacity: 1,
                filter: "blur(0px)",
                y: 0,
                transition: {
                  duration: 0.6,
                  ease: [0.22, 1, 0.36, 1],
                },
              },
            }}
          >
            <div className={styles.logoWrapper}>
              <Link
                aria-label="Go to Circle's website"
                href="https://www.circle.com/"
                className={styles.logo}
              >
                <CircleLogo className={styles.logoImage} />
              </Link>
            </div>

            <div className={styles.logoWrapper}>
              <Link
                aria-label="Go to Algorand's website"
                href="https://algorand.co/"
                className={styles.logo}
              >
                <AlgorandLogo className={styles.logoImage} />
              </Link>
            </div>

            <div className={styles.logoWrapper}>
              <Link
                aria-label="Go to Stablecorp's website"
                href="https://www.stablecorp.com/"
                className={styles.logo}
              >
                <StablecorpLogo className={styles.logoImage} />
              </Link>
            </div>
          </motion.div>
        </motion.div>
      </div>
    </section>
  );
}
